import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`conversion-rewrite`,heroTitle:`Rewrite your pages for conversions`,heroSubtitle:`Perplexity Computer analyzes your landing page, finds conversion gaps, and rewrites the copy into a sharper offer, proof points, and CTA flow.`,inputUrlCta:`Rewrite this page`,inputUrlPlaceholder:`your landing page URL`,inputUrlPrefill:`Go to {url} and rewrite this landing page for stronger conversions. 1) Analyze the headline, offer, audience, proof, objections, page structure, and CTA clarity. 2) Identify friction points, missing proof, weak claims, unclear benefits, and mismatches between traffic intent and page copy. 3) Rewrite the hero, section headings, benefit bullets, proof blocks, objection handling, FAQ, and CTA language. 4) Provide an A/B test plan with hypotheses, variants, and success metrics. 5) Deliver a conversion-focused page brief with final copy ready to paste into the site.`,heroOverlaySteps:[`Analyzing offer clarity, proof, objections, and CTA flow`,`Identifying friction points and weak conversion moments`,`Rewriting headlines, sections, benefit bullets, and FAQs`,`Conversion copy and A/B test plan ready to publish`],generatingSteps:[`Visiting {url} to understand the offer, audience, proof, and page structure`,`Designing an agent to audit conversion friction and message match`,`Configuring rewritten copy blocks, CTA variants, and objection handling`,`Setting up the final conversion brief and A/B test plan`],featureSectionTitle:`From page audit to conversion-ready copy`,featureCardTitles:[`Connects to your marketing stack`,`Outputs you can test`],featureCardDescriptions:[`Computer breaks the rewrite into page analysis, message strategy, proof mapping, copywriting, and test planning steps.`,`Landing pages, ad campaigns, analytics notes, Docs, Notion, and Slack can feed one organized conversion workflow.`,`Hero copy. Section rewrites. CTA variants. FAQ updates. A/B test plan. Computer delivers copy your team can ship and measure.`],capabilitySectionTitle:`Your conversion copywriter, on autopilot`,capabilitySectionSubtitle:`Paste a landing page URL and get a sharper page rewrite with test ideas.`,capabilityCards:[{title:`Page Message Audit`,description:`Computer can analyze the headline, offer, audience fit, proof, objections, and CTA clarity across a landing page.`},{title:`Conversion Gap Finder`,description:`Computer can identify friction points, missing proof, weak benefits, and unclear calls to action.`},{title:`Copy Rewrite`,description:`Computer can rewrite hero sections, benefit bullets, proof blocks, FAQs, and CTA language for stronger conversion intent.`},{title:`Connect Your Tools`,description:`Computer can organize page URLs, campaign notes, analytics exports, Docs, Notion, and Slack feedback into one workflow.`},{title:`Remember Your Voice`,description:`Computer can remember your brand voice, compliance notes, proof standards, and preferred offer structure.`},{title:`Test Plan Monitoring`,description:`Computer can prepare A/B test hypotheses and help monitor results so the next rewrite starts from measured learnings.`}]});export{t as default};
